import math
from collections import Counter

def vec(text):
    return Counter(text.split())

def cosine(a, b):
    va, vb = vec(a), vec(b)
    dot = sum(va[t] * vb.get(t, 0) for t in va)
    na = math.sqrt(sum(v * v for v in va.values()))
    nb = math.sqrt(sum(v * v for v in vb.values()))
    return 0.0 if not na or not nb else dot / (na * nb)

print(round(cosine("ai agent", "ai agents"), 3))
print(round(cosine("ai agent", "cats dogs"), 3))
print(round(cosine("ai agents ai", "ai agents"), 3))
